#!/usr/bin/env python3
"""Apply v3.5.39 on top of v3.5.38. Run from the repo root."""
import json, pathlib, py_compile, sys
D = json.loads('{"pairs": [["backend/app/config.py", "    # timed stand-down rather than a halt for the day.\\n    risk_stand_down_sec: float = 3600.0\\n    auto_squareoff_ist: str = \\"23:25\\"    # advise square-off after this IST time\\n\\n    # --- Paper auto-trading (simulated fills only; NEVER places live orders) ---\\n", "    # timed stand-down rather than a halt for the day.\\n    risk_stand_down_sec: float = 3600.0\\n    auto_squareoff_ist: str = \\"23:15\\"    # advise square-off after this IST time\\n\\n    # --- Paper auto-trading (simulated fills only; NEVER places live orders) ---\\n"], ["backend/app/config.py", "    vol_levels_enabled: bool = True\\n    vol_atr_period: int = 14\\n    vol_stop_atr_mult: float = 2.0\\n    vol_target_atr_mults: list[float] = [3.0, 5.0, 8.0]\\n", "    vol_levels_enabled: bool = True\\n    vol_atr_period: int = 14\\n    # Re-fetch an option\'s 1-min candles after this many seconds so the option ATR\\n    # (and the option chart) stay current; the fetch is non-blocking and shares the\\n    # historical rate budget, the old candles are kept until it succeeds. 0 = never.\\n    option_candles_refresh_sec: float = 180.0\\n    vol_stop_atr_mult: float = 2.0\\n    vol_target_atr_mults: list[float] = [3.0, 5.0, 8.0]\\n"], ["backend/app/config.py", "    # LIVE intraday square-off (IST): flatten and stop new live entries after\\n    # this time. Set a few minutes before the broker\'s own intraday cut-off.\\n    auto_trade_live_squareoff_equity_ist: str = \\"15:20\\"\\n    auto_trade_live_squareoff_mcx_ist: str = \\"23:00\\"\\n\\n    # --- Zero-to-Hero expiry sleeve (SPECULATIVE, HIGH RISK, SEPARATE budget) ---\\n", "    # LIVE intraday square-off (IST): flatten and stop new live entries after\\n    # this time. Set a few minutes before the broker\'s own intraday cut-off.\\n    auto_trade_live_squareoff_equity_ist: str = \\"15:15\\"\\n    auto_trade_live_squareoff_mcx_ist: str = \\"23:15\\"\\n\\n    # --- Zero-to-Hero expiry sleeve (SPECULATIVE, HIGH RISK, SEPARATE budget) ---\\n"], ["backend/app/market/angelone.py", "        self._fut_candles: list[Candle] = []\\n        self._opt_candles: dict[str, list[Candle]] = {}\\n        self._last_quote_at = 0.0\\n        self._last_fut_candles_at = 0.0\\n", "        self._fut_candles: list[Candle] = []\\n        self._opt_candles: dict[str, list[Candle]] = {}\\n        self._opt_candles_at: dict[str, float] = {}\\n        self._last_quote_at = 0.0\\n        self._last_fut_candles_at = 0.0\\n"], ["backend/app/market/angelone.py", "            return []\\n        cached = self._opt_candles.get(symbol)\\n        if cached:\\n            return cached[-limit:]\\n        if self._shard.hist.warming_count():\\n            # An instrument still has no futures history: its first candles\\n            # outrank an option chart, or it can starve on the shared budget.\\n", "            return []\\n        cached = self._opt_candles.get(symbol)\\n        ttl = float(settings.option_candles_refresh_sec or 0)\\n        fresh = time.time() - getattr(self, \\"_opt_candles_at\\", {}).get(symbol, 0.0) < ttl\\n        if cached and (ttl <= 0 or fresh):\\n            return cached[-limit:]\\n        if not cached and self._shard.hist.warming_count():\\n            # An instrument still has no futures history: its first candles\\n            # outrank an option chart, or it can starve on the shared budget.\\n"], ["backend/app/market/angelone.py", "        if candles:\\n            self._opt_candles[symbol] = candles\\n        return candles[-limit:]\\n\\n", "        if candles:\\n            self._opt_candles[symbol] = candles\\n            if not hasattr(self, \\"_opt_candles_at\\"):\\n                self._opt_candles_at = {}\\n            self._opt_candles_at[symbol] = time.time()\\n        elif cached:\\n            return cached[-limit:]\\n        return candles[-limit:]\\n\\n"]], "smoke": "\\"\\"\\"Smoke v3.5.39: Angel option 1-min candles refresh after option_candles_refresh_sec\\n(old candles kept until the refetch succeeds); square-off defaults 15:15 / 23:15.\\nNo broker: the historical fetch is faked.\\"\\"\\"\\nimport os\\nimport tempfile\\nimport time\\n\\nos.environ.setdefault(\\"QT_DATA_DIR\\", tempfile.mkdtemp())\\nfrom types import SimpleNamespace  # noqa: E402\\n\\nfrom app.config import settings  # noqa: E402\\nfrom app.market import angelone  # noqa: E402\\nfrom app.models import Candle  # noqa: E402\\n\\nFAIL = []\\n\\n\\ndef check(name, ok, info=\\"\\"):\\n    print((\\"PASS \\" if ok else \\"FAIL \\") + name + (\\"\\" if ok else f\\" \\u2014 {info}\\"))\\n    if not ok:\\n        FAIL.append(name)\\n\\n\\nCALLS = []\\nNEXT = {\\"rows\\": [1]}\\nangelone._historical_candles = lambda shard, params, blocking: (CALLS.append(params) or (NEXT[\\"rows\\"], \\"\\"))\\nangelone._to_candles = lambda rows: [Candle(time=i, open=10, high=11, low=9, close=10, volume=1) for i in rows]\\np = object.__new__(angelone.AngelOneProvider)\\np._options = [SimpleNamespace(symbol=\\"X\\", token=\\"1\\")]\\np._opt_candles = {}\\np._opt_candles_at = {}\\np._exchange = \\"MCX\\"\\np._shard = SimpleNamespace(hist=SimpleNamespace(warming_count=lambda: 0))\\nsettings.option_candles_refresh_sec = 180.0\\ncheck(\\"first call fetches\\", len(p.option_candles(\\"X\\")) == 1 and len(CALLS) == 1)\\nNEXT[\\"rows\\"] = [1, 2]\\ncheck(\\"within refresh window: cached, no fetch\\", len(p.option_candles(\\"X\\")) == 1 and len(CALLS) == 1)\\np._opt_candles_at[\\"X\\"] -= 200\\ncheck(\\"after refresh window: refetched\\", len(p.option_candles(\\"X\\")) == 2 and len(CALLS) == 2)\\np._opt_candles_at[\\"X\\"] -= 200\\nNEXT[\\"rows\\"] = []\\ncheck(\\"failed refetch keeps old candles\\", len(p.option_candles(\\"X\\")) == 2 and len(CALLS) == 3)\\nsettings.option_candles_refresh_sec = 0\\nNEXT[\\"rows\\"] = [1, 2, 3]\\ncheck(\\"0 = never refresh\\", len(p.option_candles(\\"X\\")) == 2 and len(CALLS) == 3)\\ncheck(\\"square-off defaults 15:15 / 23:15\\",\\n      type(settings)().auto_trade_live_squareoff_equity_ist == \\"15:15\\"\\n      and type(settings)().auto_trade_live_squareoff_mcx_ist == \\"23:15\\", \\"\\")\\nprint(\\"ALL PASS\\" if not FAIL else f\\"{len(FAIL)} FAIL: {FAIL}\\")\\nraise SystemExit(1 if FAIL else 0)\\n"}')
cfg = pathlib.Path("backend/app/config.py").read_text()
if "option_candles_refresh_sec" in cfg:
    sys.exit("ABORT: v3.5.39 already applied")
if "vol_atr_period" not in cfg:
    sys.exit("ABORT: v3.5.38 not applied yet (run qt_v3538_apply.py first)")
texts = {}
for f, old, new in D["pairs"]:
    s = texts.get(f) or pathlib.Path(f).read_text()
    if s.count(old) != 1:
        sys.exit("ABORT: anchor not found once in " + f + ": " + old[:80])
    texts[f] = s.replace(old, new)
for f, s in texts.items():
    pathlib.Path(f).write_text(s)
pathlib.Path("backend/_smoke_v3539.py").write_text(D["smoke"])
for f in list(texts) + ["backend/_smoke_v3539.py"]:
    py_compile.compile(f, doraise=True)
print("v3.5.39 applied OK")
